import{_ as i,o as s,c as t,a4 as o}from"./chunks/framework.CmuCl-jw.js";const k=JSON.parse('{"title":"Installation of Arcsecond.local","description":"","frontmatter":{},"headers":[],"relativePath":"local/installation.md","filePath":"local/installation.md"}'),a={name:"local/installation.md"};function n(l,e,r,c,h,d){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="installation-of-arcsecond-local" tabindex="-1">Installation of Arcsecond.local <a class="header-anchor" href="#installation-of-arcsecond-local" aria-label="Permalink to “Installation of Arcsecond.local”">​</a></h1><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>As of now, the installation of Arcsecond.local requires an individual authentication token, provided manually by Arcsecond. In the future, the process will be streamlined and easier.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before proceeding with the installation, ensure that you have the following prerequisites met:</p><ul><li>A PC with sufficient resources (CPU, RAM, disk space) to run Arcsecond.local. The recommended settings are a recent CPU, 2GB+ of RAM (depending on number of potential users). Moreover, for normal operations, outside any consideration of long-term data storage, Arcsecond requires at least 50GB of disk storage to operate. It is used for database backups, astrometry cache, temporary images data etc.</li><li><a href="https://docker.io" target="_blank" rel="noreferrer">Docker</a> is installed on your PC.</li><li><a href="https://pip.pypa.io/en/stable/installation/" target="_blank" rel="noreferrer">pip</a> is available on your PC (you can open a Terminal and type <code>pip3 --version</code> to check first).</li><li>Access to the Arcsecond Docker private registry, via the personal authentication token (PAT). <a href="mailto:team@arcsecond.io" target="_blank" rel="noreferrer">Contact us</a> to obtain yours.</li></ul><div class="tip custom-block"><p class="custom-block-title">You probably already have <code>pip</code></p><p><code>pip</code> is bundled with Python itself, and has been for many years. If you installed a recent Python (3.13, 3.14, or any 3.x from python.org, from the macOS or Windows installers), <code>pip</code> came with it and there is <strong>nothing more to install</strong>. Check with:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>or, equivalently and more reliably when several Pythons are installed:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If either prints a version, you are done. The only common case where <code>pip</code> is genuinely missing is a Linux distribution that ships it as a separate package — on Debian/Ubuntu, <code>sudo apt install python3-pip</code>.</p><p>On Windows, use <code>python -m pip --version</code> instead, and see <a href="/cli/install-windows">Installing on Windows</a> if the command is not recognised.</p></div><div class="tip custom-block"><p class="custom-block-title">Docker needs no admin account, and no Docker account</p><p>Two frequent worries, both unfounded:</p><ul><li><strong>You do not need a superuser / administrator account</strong> to get Docker Desktop onto the machine: it can be installed under a regular user account.</li><li><strong>You do not need a Docker account</strong> to run Arcsecond.local. Docker Desktop shows a sign-in screen on first launch — you can simply skip it. The only login involved is the one to the <em>Arcsecond</em> registry with your PAT, described below, which is unrelated to Docker Hub.</li></ul><p>One exception, on <strong>Linux with Docker Engine</strong> (no Docker Desktop): the daemon only answers root and members of the <code>docker</code> group. If <code>docker compose up -d</code> ends with <code>permission denied while trying to connect to the docker API at unix:///var/run/docker.sock</code>, add your user to that group once, then log out and back in (or open a new shell with <code>newgrp docker</code>):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span></code></pre></div></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The installation of Arcsecond requires you to write some simple commands in the Terminal. On *nix machines, you can use any shell.</p><p>On Windows, <strong>PowerShell is enough</strong> — it is installed by default, and every command below works in it. The <a href="https://learn.microsoft.com/en-us/windows/wsl/install" target="_blank" rel="noreferrer">WSL</a> (Windows Subsystem for Linux) is <strong>not mandatory</strong>: install it only if you specifically want a <code>bash</code> shell and a small Linux distribution (&quot;Distro&quot;, typically Ubuntu).</p></div><div class="warning custom-block"><p class="custom-block-title">Do not use WSL for the Live-Image Proxy</p><p>If you plan to plug USB webcams or all-sky cameras into the Windows machine, the Arcsecond CLI <strong>must</strong> run natively in PowerShell: WSL has no direct access to the host&#39;s USB devices. See the <a href="/local/webcam">Live-Image Proxy</a> page.</p></div><ul><li>Open the Terminal.</li><li>Install the Arcsecond CLI: <code>pip3 install arcsecond</code>.</li><li>Verify the installation was successful by running <code>arcsecond --version</code>.</li><li>Create a directory where everything related to Arcsecond will be stored, and go inside it, with the terminal.</li><li>Run the basic setup: <code>arcsecond setup</code>.</li><li>You can check that you have a new <code>.env</code> file in the current directory, containing some secret keys.</li><li>You should also have a file named <code>docker-compose.yml</code> with the Arcsecond system configuration.</li><li>Have your PAT with you, and login once in the Arcsecond Docker registry (replace <code>&lt;PAT&gt;</code> with your PAT): <code>echo &lt;PAT&gt; | docker login ghcr.io -u arcsecond-io --password-stdin</code></li><li>You can now start Arcsecond.local with the command: <code>docker compose up -d</code>. <strong>The first time, Docker will download all the required images. It may take some time.</strong></li></ul><p>::: warn By convention, the chevrons indicate placeholders in the documentation. Hence, you must also remove them when inserting your PAT. For instance: <code>echo ghp_XXX... | docker login...</code> and not <code>echo &lt;ghp_XXX...&gt; | docker login...</code> :::</p><h3 id="windows-adding-python-s-scripts-folder-to-path" tabindex="-1">Windows: adding Python&#39;s <code>Scripts</code> folder to <code>PATH</code> <a class="header-anchor" href="#windows-adding-python-s-scripts-folder-to-path" aria-label="Permalink to “Windows: adding Python&#39;s Scripts folder to PATH”">​</a></h3><p>On Windows, <code>pip</code> installs the <code>arcsecond</code> command as <code>arcsecond.exe</code> inside the <code>Scripts\\</code> folder of your Python installation. If that folder is not listed in the <code>PATH</code> environment variable, the installation succeeds but the command is not found:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond : The term &#39;arcsecond&#39; is not recognized as the name of a cmdlet,</span></span>
<span class="line"><span>function, script file, or operable program.</span></span></code></pre></div><p>The fix is to add that folder to <code>PATH</code>, once:</p><ol><li><p>Find the exact folder. In PowerShell:</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;import sysconfig; print(sysconfig.get_path(&#39;scripts&#39;))&quot;</span></span></code></pre></div><p>It prints something like <code>C:\\Users\\&lt;you&gt;\\AppData\\Local\\Programs\\Python\\Python314\\Scripts</code>. Copy that line.</p></li><li><p>Open the Windows environment variables editor: press the <strong>Windows key</strong>, type <em>environment</em>, and choose <strong>&quot;Edit the system environment variables&quot;</strong> (or <strong>&quot;Edit environment variables for your account&quot;</strong>). Then click the <strong>Environment Variables…</strong> button.</p></li><li><p>In the <strong>upper</strong> list (&quot;User variables for &lt;you&gt;&quot;), select the <code>Path</code> line and click <strong>Edit…</strong>.</p></li><li><p>Click <strong>New</strong>, paste the folder copied at step 1, then click <strong>OK</strong> in each of the three open windows.</p></li><li><p><strong>Close PowerShell completely and open a new window</strong> — already-open terminals keep the old <code>PATH</code>. Then check:</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arcsecond </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span></code></pre></div></li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The same thing can be done in one command, without leaving PowerShell:</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$scripts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;import sysconfig; print(sysconfig.get_path(&#39;scripts&#39;))&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$current </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::GetEnvironmentVariable(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Path&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::SetEnvironmentVariable(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Path&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$current</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Then open a fresh PowerShell window. More Windows-specific cases are covered in <a href="/cli/install-windows">Installing on Windows</a>.</p></div><h2 id="first-steps" tabindex="-1">First steps <a class="header-anchor" href="#first-steps" aria-label="Permalink to “First steps”">​</a></h2><ul><li>Arcsecond.local is now accessible at the following address: <a href="http://localhost:5555" target="_blank" rel="noreferrer">http://localhost:5555</a></li><li>That address only works on this machine. To let the rest of the observatory in from their own computers, see <a href="/local/lan-access">Access from Other Computers</a>.</li><li>You can login as <code>admin</code> / <code>admin</code>. We recommend that you change this password as soon as possible, by opening your &quot;Account&quot; panel, from the bottom-left menu.</li><li>Before exploring the Arcsecond interface, you may want to create your first observing site, by clicking on the &quot;Attach a Site&quot; button, in the the top-right of the Times bar.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>In the first moments of Arcsecond.local, various things are being loaded and integrated into the database (timezones, exoplanets, etc). You may need to wait a bit before creating your first observing site.</p></div><ul><li>On the left-hand side, you have the Sidebar, with an access to the 3 Arcsecond &quot;apps&quot;: &quot;Night Studio&quot;, &quot;Control Room&quot; and &quot;Data Grand Central&quot;.</li><li>You may want to customise your sidebar and the associated tools by opening your &quot;Settings&quot; panel from the bottom-left menu.</li></ul>`,22)])])}const u=i(a,[["render",n]]);export{k as __pageData,u as default};
